function renderNearby(){const coordinates=window.TRIP_GEO?.places||{},coverage=places.filter(p=>(coordinates[p.id]||[]).length).length;return `${header('NEAR ME','看看附近，有甚麼？','只找你已加入清單的地點 · 按直線距離由近至遠排序')}<section class="nearby-panel"><button class="locate-button" id="locateNow"${nearbyState.loading?' disabled aria-busy="true"':''}>${nearbyState.loading?'正在取得位置…':nearbyState.position?'◎ 重新定位':'◎ 定位看附近'}</button><button class="action map-pick-button" id="pickOnMap">📍 在地圖選位置</button><p class="nearby-help">手機定位：按下後請允許瀏覽器使用位置。你的位置只在這次網頁內計算，不會儲存或傳送到網站伺服器。</p><div class="chips" role="group" aria-label="附近距離範圍">${[100,200,500].map(r=>`<button class="chip ${nearbyState.radius===r?'active':''}" data-radius="${r}" aria-pressed="${nearbyState.radius===r}">${r}米</button>`).join('')}</div><div class="chips" role="group" aria-label="附近地點分類">${['全部',...exploreCats,'購物'].map(c=>`<button class="chip ${nearbyState.category===c?'active':''}" data-near-category="${c}" aria-pressed="${nearbyState.category===c}">${c==='購物'?'🛍 購物':c}</button>`).join('')}</div>${nearbyState.category==='購物'?'<p class="note">按購物清單中未買物品的「購買地點」定位。</p>':''}<div id="nearbyStatus" role="status" aria-live="polite">${nearbyState.error?`<div class="notice nearby-error">${esc(nearbyState.error)}</div>`:nearbyState.loading?'<p>定位中，請稍候…</p>':nearbyState.position&&nearbyState.mode==='manual'?'<p class="note">📍 以地圖選取的位置為中心 · 距離並非從手機目前位置計算</p>':nearbyState.position?`<p class="note">已取得位置 · 定位精度約 ±${Math.ceil(nearbyState.accuracy)}米${nearbyState.accuracy>nearbyState.radius?'；誤差大於所選範圍，建議到室外重新定位或選較大範圍。':''}</p>`:'<p class="note">尚未選取位置。選擇範圍後，可用手機定位或在地圖選位置。</p>'}</div></section><div id="nearbyResults"></div><p class="note">距離為直線估算，並非步行路程；樓層、入口及河道可能影響實際路程。已建立座標 ${coverage}/${places.length} 個地點；未有可靠座標的項目暫不納入附近結果。</p><p class="note">座標來源：店方／場地地圖及公開地點資料。<button class="action" id="nearbyCoverage">查看座標覆蓋情況</button></p>`}
function nearbyResults(){const target=$('#nearbyResults');if(!target)return;if(!nearbyState.position){target.innerHTML='';return;}if(nearbyState.category==='購物')return shoppingNearby(target);const rs=window.Nearby.find(places,window.TRIP_GEO?.places||{},nearbyState.position,nearbyState.radius,nearbyState.category);target.innerHTML=`<div class="resultsbar"><span>${nearbyState.radius}米內 · ${rs.length} 個已加入地點</span></div>${rs.length?`<div class="cardgrid">${rs.map(r=>placeCard(r.place,r)).join('')}</div>`:`<div class="empty"><h2>這個範圍內暫時沒有符合的地點</h2><p>可試試較大範圍、其他分類，或重新定位。</p><a class="action" href="#explore">查看全部地點 →</a></div>`}`}
