function refreshNearby(){if(current!=='nearby')return;$('#app').innerHTML=renderNearby()+footer();nearbyResults()}
function locateNearby(){if(nearbyState.loading)return;const request=++nearbyRequest;if(location.hash!=='#nearby')location.hash='nearby';nearbyState.error='';if(!navigator.geolocation){nearbyState.error='這個瀏覽器不支援定位，請使用手機的Safari或Chrome開啟網頁。';refreshNearby();return;}if(!window.isSecureContext){nearbyState.error='定位需要安全連線，請用HTTPS網址開啟網頁。';refreshNearby();return;}nearbyState.position=null;nearbyState.accuracy=null;nearbyState.loading=true;refreshNearby();navigator.geolocation.getCurrentPosition(pos=>{if(request!==nearbyRequest)return;nearbyState.loading=false;const {latitude,longitude,accuracy}=pos.coords;if(!Number.isFinite(latitude)||!Number.isFinite(longitude)||!Number.isFinite(accuracy)){nearbyState.error='未能取得有效位置，請重新定位。';refreshNearby();return;}nearbyState.mode='gps';nearbyState.position={lat:latitude,lng:longitude};nearbyState.accuracy=accuracy;refreshNearby()},err=>{if(request!==nearbyRequest)return;nearbyState.loading=false;nearbyState.error=({1:'未獲允許使用位置。請在瀏覽器的網站設定允許位置，再按重新定位。',2:'暫時無法取得位置。請開啟手機定位服務，或到室外再試。',3:'定位逾時。請檢查手機定位服務及網絡後再試。'})[err.code]||'定位失敗，請稍後再試。';refreshNearby()},{enableHighAccuracy:true,timeout:15000,maximumAge:30000})}
