function nearbyCoverage(){const geo=window.TRIP_GEO?.places||{},missing=places.filter(p=>!(geo[p.id]||[]).length);openDialog(`<div class="eyebrow">LOCATION COVERAGE</div><h2 class="detailtitle">座標覆蓋情況</h2><p>已建立 ${places.length-missing.length}/${places.length} 個地點座標。範圍較大的景點以標示位置計算；沒有可靠位置的項目不以區域中心代替。</p>${missing.length?`<h3>尚未納入附近結果</h3><ul>${missing.map(p=>`<li>${esc(p.v[1])}</li>`).join('')}</ul>`:'<p>所有清單地點均已建立座標。</p>'}`)}
// Sub-areas (trip/content areas): nearest centre within the place's own region, else address keywords.
const areas=C.areas||[],areaCache=new WeakMap();
function areaOf(p){
 if(areaCache.has(p))return areaCache.get(p);
 const own=areas.filter(a=>a.region===p.v[0]),pool=own.length?own:areas,pt=window.TRIP_GEO.places[p.id]?.[0];let name='';
 if(pt){const best=pool.map(a=>({a,d:window.Nearby.distance(pt,a)})).sort((x,y)=>x.d-y.d)[0];if(best&&best.d<=6000)name=best.a.name}
 if(!name){const t=`${p.v[3]} ${p.v[1]}`,hit=a=>{try{return !!a.kw&&new RegExp(a.kw).test(t)}catch{return false}};name=(pool.find(hit)||areas.find(hit))?.name||''}
 areaCache.set(p,name);return name;
}
const inRegion=p=>region==='全部區域'||(region.startsWith('a:')?areaOf(p)===region.slice(2):p.v[0]===region.slice(2));
function regionOptions(){
 const opt=(value,label)=>`<option value="${esc(value)}"${value===region?' selected':''}>${esc(label)}</option>`;
 return opt('全部區域','全部區域')+[...new Set(places.map(p=>p.v[0]))].map(r=>{
  const inR=places.filter(p=>p.v[0]===r),subs=areas.filter(a=>a.region===r).map(a=>[a.name,places.filter(p=>areaOf(p)===a.name).length]).filter(([,n])=>n);
  return subs.length?`<optgroup label="${esc(r)}">${opt('r:'+r,`${r}（全部 ${inR.length}）`)}${subs.map(([n,c])=>opt('a:'+n,`${n}（${c}）`)).join('')}</optgroup>`:opt('r:'+r,`${r}（${inR.length}）`);
 }).join('');
}
function renderExplore(){return `${header('POCKET PLACES','把喜歡的地方，收好。',G?'旅伴加入的地點 · 按「＋ 新增地點」貼上 Google 地圖連結':'依博多站由近至遠排列 · 不重複顯示分類分頁的相同地點')}<div class="nearby-inline"><a class="action primary" href="#nearby">◎ 查看附近地點（100／200／500米）</a><button class="action" data-place-new>＋ 新增地點</button></div><div class="controls"><div class="searchrow"><input id="search" class="search" type="search" placeholder="搜尋店名、美食、地址…" aria-label="搜尋地點" value="${esc(search)}"><select id="region" aria-label="選擇區域或小區">${regionOptions()}</select></div><div class="chips">${['全部',...exploreCats].map(c=>`<button class="chip ${category===c?'active':''}" data-cat="${c}">${c}</button>`).join('')}<button class="chip ${onlySaved?'active':''}" id="savedToggle">☆ 我的收藏</button></div></div><div id="results"></div>`}
