function placeForm(p){const v=i=>esc(p?.v[i]||''),pins=p?window.TRIP_GEO.places[p.id]||[]:[],pin=pins[0];openDialog(`<div class="eyebrow">${p?'EDIT PLACE':'NEW PLACE'}</div><h2 class="detailtitle">${p?'修改地點':'新增地點'}</h2><form class="tg-form" id="placeForm" data-id="${p?esc(p.id):''}"><label>Google 地圖連結<span class="searchrow"><input name="mapsUrl" class="search" inputmode="url" autocomplete="off" placeholder="貼上 Google 地圖分享連結"><button type="button" class="action primary" id="placeLookup">自動填寫</button></span></label><p class="note" id="placeLookupInfo">在 Google 地圖按「分享」→ 複製連結，貼上後按「自動填寫」。只會填入空白欄位。</p><label>名稱<input name="f1" required maxlength="80" value="${v(1)}"></label><fieldset><legend>分類</legend>${categories.map(c=>`<label class="tg-check"><input type="checkbox" name="cats" value="${c}"${p?.cats.includes(c)?' checked':''}> ${c}</label>`).join('')}</fieldset><label>區域<input name="f0" list="placeRegions" maxlength="60" required value="${v(0)}"><datalist id="placeRegions">${[...new Set(places.map(x=>x.v[0]).filter(Boolean))].map(r=>`<option value="${esc(r)}">`).join('')}</datalist></label>${placeFields.map(([i,label,max])=>`<label>${label}${max>200?`<textarea name="f${i}" rows="3" maxlength="${max}">${v(i)}</textarea>`:`<input name="f${i}" maxlength="${max}" value="${v(i)}">`}</label>`).join('')}<input type="hidden" name="lat" value="${pin?pin.lat:''}"><input type="hidden" name="lng" value="${pin?pin.lng:''}"><input type="hidden" name="mainLabel" value="${esc(pin?.label||'')}"><fieldset class="branches"><legend>其他分店／地址</legend><div id="branchRows">${pins.slice(1).map(branchRow).join('')}</div><button type="button" class="smallbtn" data-branch-add>＋ 加入分店／地址</button><p class="note">每個分店貼上 Google 地圖連結後按「定位」。附近頁會用最近的分店計算距離。</p></fieldset><button type="submit" class="locate-button">${p?'儲存修改':'加入地點'}</button></form>`)}
async function findBranch(row){const url=row.querySelector('[name=bUrl]').value.trim(),at=row.querySelector('.branch-at');if(!url)return toast('請先貼上分店的 Google 地圖連結。');at.textContent='查詢中…';try{const r=await window.Together.lookupPlace(url);if(!Number.isFinite(r.lat))throw new Error('no location');row.querySelector('[name=bLat]').value=r.lat;row.querySelector('[name=bLng]').value=r.lng;const lab=row.querySelector('[name=bLabel]');if(!lab.value.trim())lab.value=r.name||'';at.textContent='📍 '+(r.address||'已定位')}catch(e){at.textContent=String(e?.code||'').startsWith('functions/')&&e.message?e.message.replace(/\s*\[\d+\]$/,''):'未能定位'}}
async function lookupPlaceForm(){
 const f=$('#placeForm'),btn=$('#placeLookup'),info=$('#placeLookupInfo'),el=f.elements,url=el.mapsUrl.value.trim();if(!url)return toast('請先貼上 Google 地圖連結。');
 btn.disabled=true;info.textContent='正在查詢 Google 地圖…';
 try{
  const r=await window.Together.lookupPlace(url),put=(name,value)=>{if(value&&!el[name].value.trim())el[name].value=value};
  put('f1',r.name);put('f2',r.type);put('f3',r.address);put('f5',[r.price&&'價格：'+r.price,r.hours&&'時間：\n'+r.hours].filter(Boolean).join('\n'));put('f10',[r.website,r.mapsUrl].filter(Boolean).join('\n'));
  if(r.category&&![...el.cats].some(c=>c.checked))[...el.cats].forEach(c=>c.checked=c.value===r.category);
  if(Number.isFinite(r.lat)&&Number.isFinite(r.lng)){el.lat.value=r.lat;el.lng.value=r.lng;const near=places.filter(p=>p.v[0]).map(p=>({p,d:Math.min(...(window.TRIP_GEO.places[p.id]||[]).map(g=>window.Nearby.distance(r,g)),Infinity)})).sort((a,b)=>a.d-b.d)[0];if(near&&near.d<8000)put('f0',near.p.v[0])}
  put('f0',r.district);
  info.textContent='已填入，請檢查後按儲存。';
 }catch(e){info.textContent=String(e?.code||'').startsWith('functions/')&&e.message?e.message.replace(/\s*\[\d+\]$/,''):'未能自動填寫，請手動輸入。';console.error(e)}
 finally{btn.disabled=false}
}
function savePlaceForm(f){
 const v=new FormData(f),cats=v.getAll('cats').map(String);if(!cats.length)return toast('請最少選一個分類。');
 const p=places.find(x=>x.id===f.dataset.id),fields=Array.from({length:12},(_,i)=>String(p?.v[i]??''));
 for(const i of [0,1,...placeFields.map(([i])=>i)])fields[i]=String(v.get('f'+i)||'').trim();
 fields[6]=cats[0];if(!p){fields[7]='旅伴新增';fields[9]=new Date().toISOString().slice(0,10)+'｜旅伴新增'}
 const lat=parseFloat(v.get('lat')),lng=parseFloat(v.get('lng'));
 const bl=v.getAll('bLabel'),blat=v.getAll('bLat'),blng=v.getAll('bLng'),branches=bl.map((label,k)=>({lat:parseFloat(blat[k]),lng:parseFloat(blng[k]),label:String(label).trim().slice(0,60)})).filter(b=>Number.isFinite(b.lat)&&Number.isFinite(b.lng));
 const main=Number.isFinite(lat)&&Number.isFinite(lng)?[{lat,lng,label:String(v.get('mainLabel')||'').slice(0,60)}]:[],points=[...main,...branches].slice(0,10);
 window.Together.savePlace({place:p,fields,cats,lat:Number.isFinite(lat)?lat:points[0]?.lat??null,lng:Number.isFinite(lng)?lng:points[0]?.lng??null,points:points.length>1?points:[],mapsUrl:String(v.get('mapsUrl')||'').trim().slice(0,500)});
 $('#detail').close();
}
