function tripDays(m){const out=[],wk='日一二三四五六',end=Date.parse(`${m.endDate}T00:00:00Z`);for(let t=Date.parse(`${m.startDate}T00:00:00Z`),n=1;t<=end&&n<=60;t+=864e5,n++){const d=new Date(t),y=d.getUTCFullYear(),mo=d.getUTCMonth()+1,da=d.getUTCDate();out.push({n,date:`${da}/${mo}/${y}`,weekday:'星期'+wk[d.getUTCDay()],region:m.destination||'',hotel:'',transport:'',iso:`${y}/${String(mo).padStart(2,'0')}/${String(da).padStart(2,'0')}`})}return out}
