function hotelForm(h){const v=k=>esc(h?.[k]??''),first=days[0]?isoDash(days[0]):'',last=days.at(-1)?isoDash(days.at(-1)):'';openDialog(`<div class="eyebrow">STAY</div><h2 class="detailtitle">${h?'修改住宿':'新增住宿'}</h2><form class="tg-form" id="hotelForm" data-id="${h?esc(h.id):''}"><label>Google 地圖連結<span class="searchrow"><input name="mapsUrl" class="search" inputmode="url" autocomplete="off" placeholder="貼上酒店的 Google 地圖分享連結" value="${v('mapsUrl')}"><button type="button" class="action primary" id="hotelLookup">自動填寫</button></span></label><p class="note" id="hotelLookupInfo"></p><label>酒店名稱<input name="name" required maxlength="100" value="${v('name')}"></label><label>地址<input name="address" maxlength="200" value="${v('address')}"></label><div class="tg-row"><label>入住<input name="checkIn" type="date" value="${h?v('checkIn'):first}"></label><label>退房<input name="checkOut" type="date" value="${h?v('checkOut'):last}"></label></div><label>備註（訂單、早餐、寄存行李…）<textarea name="note" rows="2" maxlength="500">${v('note')}</textarea></label><input type="hidden" name="lat" value="${h?.lat??''}"><input type="hidden" name="lng" value="${h?.lng??''}"><button type="submit" class="locate-button">${h?'儲存修改':'加入住宿'}</button></form>`)}
